using Microsoft.ML.Data;

namespace TicketClassifier.Models;

public sealed class TicketData
{
    [LoadColumn(0)]
    public string Subject { get; set; } = string.Empty;

    [LoadColumn(1)]
    public string Description { get; set; } = string.Empty;

    [LoadColumn(2)]
    public float Priority { get; set; }

    [LoadColumn(3)]
    public string Category { get; set; } = string.Empty;
}

public sealed class TicketPrediction
{
    [ColumnName("PredictedLabel")]
    public string Category { get; set; } = string.Empty;

    public float[] Score { get; set; } = [];
}

namespace TicketClassifier.Models;

public sealed class TicketRequest
{
    public required string Subject { get; set; }
    public required string Description { get; set; }
    public int Priority { get; set; }
}

public sealed class TicketClassificationResult
{
    public required string PredictedCategory { get; set; }
    public required Dictionary<string, float> Confidence { get; set; }
}

public sealed class TrainingResult
{
    public required string Message { get; set; }
    public required EvaluationMetrics Metrics { get; set; }
}

public sealed class EvaluationMetrics
{
    public float MicroAccuracy { get; set; }
    public float MacroAccuracy { get; set; }
    public float LogLoss { get; set; }
    public float LogLossReduction { get; set; }
}

using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public sealed class TicketModelService
{
    private readonly MLContext _mlContext = new(seed: 42);
    private readonly string _modelPath;
    private readonly string _dataPath;
    private readonly ILogger<TicketModelService> _logger;
    private readonly string[] _categoryNames = ["Billing", "General", "Technical"];

    public TicketModelService(IWebHostEnvironment env, ILogger<TicketModelService> logger)
    {
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ticket_model.zip");
        _logger = logger;
    }

    public TrainingResult TrainAndEvaluate()
    {
        var data = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

        var pipeline = _mlContext.Transforms.Text
                .FeaturizeText("SubjectFeatures", nameof(TicketData.Subject))
            .Append(_mlContext.Transforms.Text
                .FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.MulticlassClassification.Trainers
                .SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion
                .MapKeyToValue("PredictedLabel"));

        var model = pipeline.Fit(split.TrainSet);

        var predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions);

        _logger.LogInformation(
            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        _mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        return new TrainingResult
        {
            Message = "Model trained and saved successfully.",
            Metrics = new EvaluationMetrics
            {
                MicroAccuracy = (float)metrics.MicroAccuracy,
                MacroAccuracy = (float)metrics.MacroAccuracy,
                LogLoss = (float)metrics.LogLoss,
                LogLossReduction = (float)metrics.LogLossReduction
            }
        };
    }

    public string ModelPath => _modelPath;

    public string[] CategoryNames => _categoryNames;
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketClassifierController : ControllerBase
{
    private readonly TicketModelService _modelService;
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;

    public TicketClassifierController(
        TicketModelService modelService,
        PredictionEnginePool<TicketData, TicketPrediction> predictionPool)
    {
        _modelService = modelService;
        _predictionPool = predictionPool;
    }

    [HttpPost("train")]
    public ActionResult<TrainingResult> Train()
    {
        var result = _modelService.TrainAndEvaluate();
        return Ok(result);
    }

    [HttpPost("predict")]
    public ActionResult<TicketClassificationResult> Predict([FromBody] TicketRequest request)
    {
        if (!System.IO.File.Exists(_modelService.ModelPath))
            return BadRequest("Model not trained yet. Call POST /api/ticketclassifier/train first.");

        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var confidence = new Dictionary<string, float>();
        var categories = _modelService.CategoryNames;
        for (var i = 0; i < prediction.Score.Length && i < categories.Length; i++)
            confidence[categories[i]] = prediction.Score[i];

        return Ok(new TicketClassificationResult
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        });
    }
}

